6. namespace ABLogixGitManager;
7. 
8. /// <summary>
9. /// Application entry point. Registers global exception handlers, initialises the
10. /// logger, and triggers the first-run Settings window when l5xgit is not yet configured.
11. /// </summary>
12. public partial class App : Application
13. {
14.     /// <inheritdoc/>
15.     protected override void OnStartup(StartupEventArgs e)
16.     {
17.         base.OnStartup(e);
18. 
19.         RegisterUnhandledExceptionHandlers();
20.         AppLogger.Info($"Application starting. Log file: {AppLogger.FilePath}");
21. 
22.         // Open the Settings window on first run so users know what to configure.
23.         // "First run" is defined as: l5xgit.exe path has never been saved.
24.         var config = new AppConfigService().Load();
25.         if (string.IsNullOrWhiteSpace(config.L5xGitExePath))
26.         {
27.             AppLogger.Info("First run detected — l5xgit path not configured. Scheduling Settings window.");
28. 
29.             // MainWindow is null here because StartupUri creates it after OnStartup returns.
30.             // Activated fires once the first window becomes the foreground window.
31.             EventHandler? handler = null;
32.             handler = (_, _) =>
33.             {
34.                 Activated -= handler;
35.                 AppLogger.Info("Opening Settings window for first-run configuration.");
36.                 new SettingsWindow(string.Empty) { Owner = MainWindow }.ShowDialog();
37.             };
38.             Activated += handler;
39.         }
40.     }
41. 
42.     /// <inheritdoc/>
43.     protected override void OnExit(ExitEventArgs e)
44.     {
45.         AppLogger.Info($"Application exiting with code {e.ApplicationExitCode}.");
46.         base.OnExit(e);
47.     }
48. 
49.     // -------------------------------------------------------------------------
50.     // Global exception handlers
51.     // -------------------------------------------------------------------------
52. 
53.     /// <summary>
54.     /// Registers three complementary unhandled exception handlers so that any
55.     /// crash — whether on the UI thread, a background thread, or an async task —
56.     /// is written to the log file before the process terminates.
57.     /// </summary>
58.     private void RegisterUnhandledExceptionHandlers()
59.     {
60.         // WPF dispatcher exceptions (UI thread): log and show a user-friendly message.
61.         DispatcherUnhandledException += OnDispatcherUnhandledException;
62. 
63.         // CLR domain exceptions (any non-UI thread): log only; process is about to terminate.
64.         AppDomain.CurrentDomain.UnhandledException += OnDomainUnhandledException;
65. 
66.         // Unobserved async task exceptions: log and prevent automatic process termination.
67.         TaskScheduler.UnobservedTaskException += OnUnobservedTaskException;
68.     }
69. 
70.     private void OnDispatcherUnhandledException(object sender, DispatcherUnhandledExceptionEventArgs args)
71.     {
72.         AppLogger.Error("Unhandled dispatcher exception", args.Exception);
73.         MessageBox.Show(
74.             $"An unexpected error occurred:\n\n{args.Exception.Message}\n\n" +
75.             $"Details have been written to:\n{AppLogger.FilePath}",
76.             "Unexpected Error",
77.             MessageBoxButton.OK,
78.             MessageBoxImage.Error);
79. 
80.         // Mark as handled so WPF does not terminate the process; the user can
81.         // continue if the application state is still consistent.
82.         args.Handled = true;
83.     }
84. 
85.     private static void OnDomainUnhandledException(object sender, UnhandledExceptionEventArgs args)
86.     {
87.         var ex = args.ExceptionObject as Exception;
88.         AppLogger.Error(
89.             $"Unhandled domain exception (terminating={args.IsTerminating})",
90.             ex);
91.     }
92. 
93.     private static void OnUnobservedTaskException(object? sender, UnobservedTaskExceptionEventArgs args)
94.     {
95.         AppLogger.Error("Unobserved task exception", args.Exception);
96.         // Prevent .NET from re-throwing the exception and crashing the process.
97.         args.SetObserved();
98.     }
99. }
