1. using System.Diagnostics;
2. using System.IO;
3. using System.Security.Principal;
4. using System.Xml.Linq;
5. 
6. namespace ABLogixGitManager.Services;
7. 
8. /// <summary>
9. /// Performs explicit, user-triggered dependency setup actions for developer/fallback workflows.
10. /// </summary>
11. public class DependencyInstallerService
12. {
13.     private const string RockwellVcsRepoUrl = "https://github.com/RockwellAutomation/ra-logix-designer-vcs-custom-tools.git";
14.     private const string StudioCustomToolsDestination = @"C:\Program Files (x86)\Rockwell Software\RSLogix 5000\Common\CustomToolsMenu.xml";
15. 
16.     /// <summary>
17.     /// Result of an install/build action.
18.     /// </summary>
19.     public sealed record InstallerActionResult(bool Success, string Message, string? L5xGitExePath = null);
20. 
21.     /// <summary>
22.     /// Installs the .NET 10 SDK using winget when it is not already available on PATH.
23.     /// </summary>
24.     public async Task<InstallerActionResult> InstallDotNetSdk10Async(Action<string> onOutput, CancellationToken cancellationToken = default)
25.     {
26.         AppLogger.Info("InstallDotNetSdk10Async starting.");
27.         onOutput("[sdk] Checking current .NET SDK version...");
28. 
29.         var (sdkCheckExitCode, sdkVersionOutput) = await RunProcessAsync("dotnet", ["--version"], onOutput, cancellationToken);
30.         if (sdkCheckExitCode == 0 && sdkVersionOutput.StartsWith("10.", StringComparison.Ordinal))
31.         {
32.             var msg = $"SDK already installed: {sdkVersionOutput}";
33.             AppLogger.Info($"InstallDotNetSdk10Async completed: {msg}");
34.             return new InstallerActionResult(true, msg);
35.         }
36. 
37.         onOutput("[sdk] .NET SDK 10 not detected. Checking winget availability...");
38.         var (wingetExitCode, _) = await RunProcessAsync("winget", ["--version"], onOutput, cancellationToken);
39.         if (wingetExitCode != 0)
40.         {
41.             const string msg = "winget is not available. Install .NET SDK 10 manually, then rescan.";
42.             AppLogger.Warn($"InstallDotNetSdk10Async failed: {msg}");
43.             return new InstallerActionResult(false, msg);
44.         }
45. 
46.         onOutput("[sdk] Installing .NET SDK 10 via winget...");
47.         var (installExitCode, _) = await RunProcessAsync(
48.             "winget",
49.             [
50.                 "install",
51.                 "--id", "Microsoft.DotNet.SDK.10",
52.                 "--exact",
53.                 "--source", "winget",
54.                 "--accept-package-agreements",
55.                 "--accept-source-agreements",
56.                 "--silent",
57.             ],
58.             onOutput,
59.             cancellationToken);
60. 
61.         if (installExitCode != 0)
62.         {
63.             var msg = $"winget install failed with exit code {installExitCode}.";
64.             AppLogger.Warn($"InstallDotNetSdk10Async failed: {msg}");
65.             return new InstallerActionResult(false, msg);
66.         }
67. 
68.         onOutput("[sdk] Verifying .NET SDK 10 installation...");
69.         var (postInstallExitCode, postInstallOutput) = await RunProcessAsync("dotnet", ["--version"], onOutput, cancellationToken);
70.         if (postInstallExitCode == 0 && postInstallOutput.StartsWith("10.", StringComparison.Ordinal))
71.         {
72.             var msg = $"Installed .NET SDK {postInstallOutput}.";
73.             AppLogger.Info($"InstallDotNetSdk10Async completed: {msg}");
74.             return new InstallerActionResult(true, msg);
75.         }
76. 
77.         const string verifyFailMsg = "Installation command completed, but .NET SDK 10 is still not detected on PATH.";
78.         AppLogger.Warn($"InstallDotNetSdk10Async failed: {verifyFailMsg}");
79.         return new InstallerActionResult(false, verifyFailMsg);
80.     }
81. 
82.     /// <summary>
83.     /// Clones or updates Rockwell's VCS tools repository, builds l5xgit from source, and returns the built executable path.
84.     /// </summary>
85.     public async Task<InstallerActionResult> InstallAndBuildRockwellVcsToolsAsync(Action<string> onOutput, CancellationToken cancellationToken = default)
86.     {
87.         AppLogger.Info("InstallAndBuildRockwellVcsToolsAsync starting.");
88. 
89.         onOutput("[vcs] Checking required tools: git and .NET SDK 10...");
90.         var (gitCheckExitCode, _) = await RunProcessAsync("git", ["--version"], onOutput, cancellationToken);
91.         if (gitCheckExitCode != 0)
92.         {
93.             const string msg = "Git was not detected on PATH. Install Git for Windows, then retry.";
94.             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
95.             return new InstallerActionResult(false, msg);
96.         }
97. 
98.         var (sdkCheckExitCode, sdkVersionOutput) = await RunProcessAsync("dotnet", ["--version"], onOutput, cancellationToken);
99.         if (sdkCheckExitCode != 0 || !sdkVersionOutput.StartsWith("10.", StringComparison.Ordinal))
100.         {
101.             var msg = "A compatible .NET SDK 10 was not detected. Install SDK 10 first, then retry.";
102.             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
103.             return new InstallerActionResult(false, msg);
104.         }
105. 
106.         var toolsRoot = GetToolsRoot();
107.         var repoDir = GetRockwellVcsRepoDirectory();
108.         Directory.CreateDirectory(toolsRoot);
109. 
110.         if (Directory.Exists(Path.Combine(repoDir, ".git")))
111.         {
112.             onOutput("[vcs] Updating existing local repository...");
113.             var (pullExitCode, _) = await RunProcessAsync("git", ["-C", repoDir, "pull", "--ff-only"], onOutput, cancellationToken);
114.             if (pullExitCode != 0)
115.             {
116.                 var msg = $"Failed to update repository (exit code {pullExitCode}).";
117.                 AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
118.                 return new InstallerActionResult(false, msg);
119.             }
120.         }
121.         else
122.         {
123.             if (Directory.Exists(repoDir))
124.             {
125.                 var msg = $"Directory already exists but is not a git repo: {repoDir}";
126.                 AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
127.                 return new InstallerActionResult(false, msg);
128.             }
129. 
130.             onOutput("[vcs] Cloning Rockwell VCS tools repository...");
131.             var (cloneExitCode, _) = await RunProcessAsync("git", ["clone", RockwellVcsRepoUrl, repoDir], onOutput, cancellationToken);
132.             if (cloneExitCode != 0)
133.             {
134.                 var msg = $"Failed to clone repository (exit code {cloneExitCode}).";
135.                 AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
136.                 return new InstallerActionResult(false, msg);
137.             }
138.         }
139. 
140.         onOutput("[vcs] Locating l5xgit project file...");
141.         var l5xGitProjectFile = Directory
142.             .GetFiles(repoDir, "*l5xgit*.csproj", SearchOption.AllDirectories)
143.             .OrderBy(p => p.Length)
144.             .FirstOrDefault();
145. 
146.         if (l5xGitProjectFile is null)
147.         {
148.             var msg = "Could not find a l5xgit project file in the repository.";
149.             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
150.             return new InstallerActionResult(false, msg);
151.         }
152. 
153.         var rockwellPackageSource = TryReadRockwellPackageSource(repoDir);
154.         if (!string.IsNullOrWhiteSpace(rockwellPackageSource) && !Directory.Exists(rockwellPackageSource))
155.         {
156.             var msg = $"Rockwell SDK package source not found at '{rockwellPackageSource}'. Continuing build because alternate package sources may satisfy restore.";
157.             onOutput($"[vcs] {msg}");
158.             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync warning: {msg}");
159.         }
160. 
161.         onOutput($"[vcs] Building project: {l5xGitProjectFile}");
162.         var (buildExitCode, _) = await RunProcessAsync(
163.             "dotnet",
164.             ["build", l5xGitProjectFile, "-c", "Release"],
165.             onOutput,
166.             cancellationToken);
167. 
168.         if (buildExitCode != 0)
169.         {
170.             var msg = $"dotnet build failed (exit code {buildExitCode}).";
171.             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
172.             return new InstallerActionResult(false, msg);
173.         }
174. 
175.         var projectDirectory = Path.GetDirectoryName(l5xGitProjectFile) ?? repoDir;
176.         var outputExe = Directory
177.             .GetFiles(projectDirectory, "l5xgit.exe", SearchOption.AllDirectories)
178.             .Where(path => path.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}Release{Path.DirectorySeparatorChar}", StringComparison.OrdinalIgnoreCase))
179.             .OrderByDescending(File.GetLastWriteTimeUtc)
180.             .FirstOrDefault()
181.             ?? Directory
182.                 .GetFiles(repoDir, "l5xgit.exe", SearchOption.AllDirectories)
183.                 .OrderByDescending(File.GetLastWriteTimeUtc)
184.                 .FirstOrDefault();
185. 
186.         if (string.IsNullOrWhiteSpace(outputExe) || !File.Exists(outputExe))
187.         {
188.             const string msg = "Build completed, but l5xgit.exe was not found in build outputs.";
189.             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
190.             return new InstallerActionResult(false, msg);
191.         }
192. 
193.         AppLogger.Info($"InstallAndBuildRockwellVcsToolsAsync completed successfully. l5xgit.exe: {outputExe}");
194.         onOutput($"[vcs] Built l5xgit.exe: {outputExe}");
195.         return new InstallerActionResult(true, "Rockwell VCS tools were built successfully.", outputExe);
196.     }
197. 
198.     /// <summary>
199.     /// Copies the built CustomToolsMenu.xml into the Studio 5000 common folder, backing up any existing file.
200.     /// If elevation is required, requests UAC consent for the copy step.
201.     /// </summary>
202.     public async Task<InstallerActionResult> InstallStudioCustomToolsMenuAsync(Action<string> onOutput, CancellationToken cancellationToken = default)
203.     {
204.         AppLogger.Info("InstallStudioCustomToolsMenuAsync starting.");
205. 
206.         var repoDir = GetRockwellVcsRepoDirectory();
207.         var source = Path.Combine(repoDir, "artifacts", "bin", "Release", "Assets", "CustomToolsMenu.xml");
208.         var destination = StudioCustomToolsDestination;
209.         var destinationDirectory = Path.GetDirectoryName(destination) ?? string.Empty;
210. 
211.         if (!File.Exists(source))
212.         {
213.             var msg = $"Source file not found: {source}. Build Rockwell VCS tools first.";
214.             AppLogger.Warn($"InstallStudioCustomToolsMenuAsync failed: {msg}");
215.             return new InstallerActionResult(false, msg);
216.         }
217. 
218.         if (!Directory.Exists(destinationDirectory))
219.         {
220.             var msg = $"Studio 5000 common directory not found: {destinationDirectory}. Is Logix Designer installed?";
221.             AppLogger.Warn($"InstallStudioCustomToolsMenuAsync failed: {msg}");
222.             return new InstallerActionResult(false, msg);
223.         }
224. 
225.         onOutput("[studio] Installing CustomToolsMenu.xml into Studio 5000 common directory...");
226. 
227.         if (IsRunningAsAdministrator())
228.         {
229.             try
230.             {
231.                 var backupPath = BackupExistingDestination(destination);
232.                 if (backupPath is not null)
233.                     onOutput($"[studio] Backed up existing file to: {backupPath}");
234. 
235.                 File.Copy(source, destination, overwrite: true);
236.                 var msg = $"Installed CustomToolsMenu.xml to {destination}.";
237.                 AppLogger.Info($"InstallStudioCustomToolsMenuAsync completed: {msg}");
238.                 return new InstallerActionResult(true, msg);
239.             }
240.             catch (Exception ex)
241.             {
242.                 AppLogger.Error("InstallStudioCustomToolsMenuAsync copy failed.", ex);
243.                 return new InstallerActionResult(false, $"Failed to install custom tools menu: {ex.Message}");
244.             }
245.         }
246. 
247.         onOutput("[studio] Requesting administrator privileges for Studio 5000 custom tools install...");
248.         var elevationResult = await RunElevatedStudioCustomToolsInstallAsync(source, destination, cancellationToken);
249.         if (!elevationResult.Success)
250.         {
251.             AppLogger.Warn($"InstallStudioCustomToolsMenuAsync failed: {elevationResult.Message}");
252.             return elevationResult;
253.         }
254. 
255.         AppLogger.Info($"InstallStudioCustomToolsMenuAsync completed: {elevationResult.Message}");
256.         return elevationResult;
257.     }
258. 
259.     private static string? TryReadRockwellPackageSource(string repoDir)
260.     {
261.         try
262.         {
263.             var nugetConfigPath = Path.Combine(repoDir, "nuget.config");
264.             if (!File.Exists(nugetConfigPath))
265.                 return null;
266. 
267.             var doc = XDocument.Load(nugetConfigPath);
268.             var sourceElement = doc
269.                 .Descendants("add")
270.                 .FirstOrDefault(x =>
271.                     string.Equals((string?)x.Attribute("key"), "rockwell-local-packages", StringComparison.OrdinalIgnoreCase));
272. 
273.             var value = (string?)sourceElement?.Attribute("value");
274.             if (string.IsNullOrWhiteSpace(value))
275.                 return null;
276. 
277.             var normalized = value.Replace('/', Path.DirectorySeparatorChar);
278.             return Path.GetFullPath(normalized);
279.         }
280.         catch (Exception ex)
281.         {
282.             AppLogger.Warn($"Unable to parse nuget.config for Rockwell package source. {ex.Message}");
283.             return null;
284.         }
285.     }
286. 
287.     private static string GetToolsRoot()
288.     {
289.         return Path.Combine(
290.             Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
291.             "ABLogixGitManager",
292.             "tools");
293.     }
294. 
295.     private static string GetRockwellVcsRepoDirectory()
296.     {
297.         return Path.Combine(GetToolsRoot(), "ra-logix-designer-vcs-custom-tools");
298.     }
299. 
300.     private static bool IsRunningAsAdministrator()
301.     {
302.         var identity = WindowsIdentity.GetCurrent();
303.         var principal = new WindowsPrincipal(identity);
304.         return principal.IsInRole(WindowsBuiltInRole.Administrator);
305.     }
306. 
307.     private static string? BackupExistingDestination(string destinationPath)
308.     {
309.         if (!File.Exists(destinationPath))
310.             return null;
311. 
312.         var index = 1;
313.         var backupPath = $"{destinationPath}.bak{index}";
314.         while (File.Exists(backupPath))
315.         {
316.             index++;
317.             backupPath = $"{destinationPath}.bak{index}";
318.         }
319. 
320.         File.Move(destinationPath, backupPath);
321.         return backupPath;
322.     }
323. 
324.     private static async Task<InstallerActionResult> RunElevatedStudioCustomToolsInstallAsync(
325.         string sourcePath,
326.         string destinationPath,
327.         CancellationToken cancellationToken)
328.     {
329.         var scriptPath = Path.Combine(Path.GetTempPath(), $"ablogix-install-customtools-{Guid.NewGuid():N}.ps1");
330.         var scriptContent = """
331. param(
332.     [Parameter(Mandatory = $true)][string]$SourcePath,
333.     [Parameter(Mandatory = $true)][string]$DestinationPath
334. )
335. $ErrorActionPreference = 'Stop'
336. $destDir = Split-Path $DestinationPath -Parent
337. if (-not (Test-Path $destDir)) { throw "Destination directory not found: $destDir" }
338. if (-not (Test-Path $SourcePath)) { throw "Source file not found: $SourcePath" }
339. if (Test-Path $DestinationPath) {
340.     $i = 1
341.     while (Test-Path "$DestinationPath.bak$i") { $i++ }
342.     Move-Item -Path $DestinationPath -Destination "$DestinationPath.bak$i"
343. }
344. Copy-Item -Path $SourcePath -Destination $DestinationPath -Force
345. """;
346. 
347.         try
348.         {
349.             File.WriteAllText(scriptPath, scriptContent);
350. 
351.             var psi = new ProcessStartInfo("powershell")
352.             {
353.                 UseShellExecute = true,
354.                 Verb = "runas",
355.             };
356.             psi.ArgumentList.Add("-NoProfile");
357.             psi.ArgumentList.Add("-ExecutionPolicy");
358.             psi.ArgumentList.Add("Bypass");
359.             psi.ArgumentList.Add("-File");
360.             psi.ArgumentList.Add(scriptPath);
361.             psi.ArgumentList.Add("-SourcePath");
362.             psi.ArgumentList.Add(sourcePath);
363.             psi.ArgumentList.Add("-DestinationPath");
364.             psi.ArgumentList.Add(destinationPath);
365. 
366.             using var process = Process.Start(psi);
367.             if (process is null)
368.                 return new InstallerActionResult(false, "Failed to start elevated install process.");
369. 
370.             await process.WaitForExitAsync(cancellationToken);
371. 
372.             if (process.ExitCode != 0)
373.                 return new InstallerActionResult(false, $"Elevated install failed with exit code {process.ExitCode}.");
374. 
375.             return new InstallerActionResult(true, $"Installed CustomToolsMenu.xml to {destinationPath}.");
376.         }
377.         catch (OperationCanceledException)
378.         {
379.             return new InstallerActionResult(false, "Custom tools menu install was cancelled.");
380.         }
381.         catch (Exception ex)
382.         {
383.             return new InstallerActionResult(false, $"Failed to install Studio 5000 custom tools menu: {ex.Message}");
384.         }
385.         finally
386.         {
387.             try
388.             {
389.                 if (File.Exists(scriptPath))
390.                     File.Delete(scriptPath);
391.             }
392.             catch (Exception ex)
393.             {
