 using System.Diagnostics;
 using System.IO;
 using System.Security.Principal;
 using System.Xml.Linq;

 namespace ABLogixGitManager.Services;

 /// <summary>
 /// Performs explicit, user-triggered dependency setup actions for developer/fallback workflows.
 /// </summary>
 public class DependencyInstallerService
 {
     private const string RockwellVcsRepoUrl = "https://github.com/RockwellAutomation/ra-logix-designer-vcs-custom-tools.git";
     private const string StudioCustomToolsDestination = @"C:\Program Files (x86)\Rockwell Software\RSLogix 5000\Common\CustomToolsMenu.xml";

     /// <summary>
     /// Result of an install/build action.
     /// </summary>
     public sealed record InstallerActionResult(bool Success, string Message, string? L5xGitExePath = null);

     /// <summary>
     /// Installs the .NET 10 SDK using winget when it is not already available on PATH.
     /// </summary>
     public async Task<InstallerActionResult> InstallDotNetSdk10Async(Action<string> onOutput, CancellationToken cancellationToken = default)
     {
         AppLogger.Info("InstallDotNetSdk10Async starting.");
         onOutput("[sdk] Checking current .NET SDK version...");

         var (sdkCheckExitCode, sdkVersionOutput) = await RunProcessAsync("dotnet", ["--version"], onOutput, cancellationToken);
         if (sdkCheckExitCode == 0 && sdkVersionOutput.StartsWith("10.", StringComparison.Ordinal))
         {
             var msg = $"SDK already installed: {sdkVersionOutput}";
             AppLogger.Info($"InstallDotNetSdk10Async completed: {msg}");
             return new InstallerActionResult(true, msg);
         }

         onOutput("[sdk] .NET SDK 10 not detected. Checking winget availability...");
         var (wingetExitCode, _) = await RunProcessAsync("winget", ["--version"], onOutput, cancellationToken);
         if (wingetExitCode != 0)
         {
             const string msg = "winget is not available. Install .NET SDK 10 manually, then rescan.";
             AppLogger.Warn($"InstallDotNetSdk10Async failed: {msg}");
             return new InstallerActionResult(false, msg);
         }

         onOutput("[sdk] Installing .NET SDK 10 via winget...");
         var (installExitCode, _) = await RunProcessAsync(
             "winget",
             [
                 "install",
                 "--id", "Microsoft.DotNet.SDK.10",
                 "--exact",
                 "--source", "winget",
                 "--accept-package-agreements",
                 "--accept-source-agreements",
                 "--silent",
             ],
             onOutput,
             cancellationToken);

         if (installExitCode != 0)
         {
             var msg = $"winget install failed with exit code {installExitCode}.";
             AppLogger.Warn($"InstallDotNetSdk10Async failed: {msg}");
             return new InstallerActionResult(false, msg);
         }

         onOutput("[sdk] Verifying .NET SDK 10 installation...");
         var (postInstallExitCode, postInstallOutput) = await RunProcessAsync("dotnet", ["--version"], onOutput, cancellationToken);
         if (postInstallExitCode == 0 && postInstallOutput.StartsWith("10.", StringComparison.Ordinal))
         {
             var msg = $"Installed .NET SDK {postInstallOutput}.";
             AppLogger.Info($"InstallDotNetSdk10Async completed: {msg}");
             return new InstallerActionResult(true, msg);
         }

         const string verifyFailMsg = "Installation command completed, but .NET SDK 10 is still not detected on PATH.";
         AppLogger.Warn($"InstallDotNetSdk10Async failed: {verifyFailMsg}");
         return new InstallerActionResult(false, verifyFailMsg);
     }

     /// <summary>
     /// Clones or updates Rockwell's VCS tools repository, builds l5xgit from source, and returns the built executable path.
     /// </summary>
     public async Task<InstallerActionResult> InstallAndBuildRockwellVcsToolsAsync(Action<string> onOutput, CancellationToken cancellationToken = default)
     {
         AppLogger.Info("InstallAndBuildRockwellVcsToolsAsync starting.");

         onOutput("[vcs] Checking required tools: git and .NET SDK 10...");
         var (gitCheckExitCode, _) = await RunProcessAsync("git", ["--version"], onOutput, cancellationToken);
         if (gitCheckExitCode != 0)
         {
             const string msg = "Git was not detected on PATH. Install Git for Windows, then retry.";
             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
             return new InstallerActionResult(false, msg);
         }

         var (sdkCheckExitCode, sdkVersionOutput) = await RunProcessAsync("dotnet", ["--version"], onOutput, cancellationToken);
         if (sdkCheckExitCode != 0 || !sdkVersionOutput.StartsWith("10.", StringComparison.Ordinal))
         {
             var msg = "A compatible .NET SDK 10 was not detected. Install SDK 10 first, then retry.";
             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
             return new InstallerActionResult(false, msg);
         }

         var toolsRoot = GetToolsRoot();
         var repoDir = GetRockwellVcsRepoDirectory();
         Directory.CreateDirectory(toolsRoot);

         if (Directory.Exists(Path.Combine(repoDir, ".git")))
         {
             onOutput("[vcs] Updating existing local repository...");
             var (pullExitCode, _) = await RunProcessAsync("git", ["-C", repoDir, "pull", "--ff-only"], onOutput, cancellationToken);
             if (pullExitCode != 0)
             {
                 var msg = $"Failed to update repository (exit code {pullExitCode}).";
                 AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
                 return new InstallerActionResult(false, msg);
             }
         }
         else
         {
             if (Directory.Exists(repoDir))
             {
                 var msg = $"Directory already exists but is not a git repo: {repoDir}";
                 AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
                 return new InstallerActionResult(false, msg);
             }

             onOutput("[vcs] Cloning Rockwell VCS tools repository...");
             var (cloneExitCode, _) = await RunProcessAsync("git", ["clone", RockwellVcsRepoUrl, repoDir], onOutput, cancellationToken);
             if (cloneExitCode != 0)
             {
                 var msg = $"Failed to clone repository (exit code {cloneExitCode}).";
                 AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
                 return new InstallerActionResult(false, msg);
             }
         }

         onOutput("[vcs] Locating l5xgit project file...");
         var l5xGitProjectFile = Directory
             .GetFiles(repoDir, "*l5xgit*.csproj", SearchOption.AllDirectories)
             .OrderBy(p => p.Length)
             .FirstOrDefault();

         if (l5xGitProjectFile is null)
         {
             var msg = "Could not find a l5xgit project file in the repository.";
             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
             return new InstallerActionResult(false, msg);
         }

         var rockwellPackageSource = TryReadRockwellPackageSource(repoDir);
         if (!string.IsNullOrWhiteSpace(rockwellPackageSource) && !Directory.Exists(rockwellPackageSource))
         {
             var msg = $"Rockwell SDK package source not found at '{rockwellPackageSource}'. Continuing build because alternate package sources may satisfy restore.";
             onOutput($"[vcs] {msg}");
             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync warning: {msg}");
         }

         onOutput($"[vcs] Building project: {l5xGitProjectFile}");
         var (buildExitCode, _) = await RunProcessAsync(
             "dotnet",
             ["build", l5xGitProjectFile, "-c", "Release"],
             onOutput,
             cancellationToken);

         if (buildExitCode != 0)
         {
             var msg = $"dotnet build failed (exit code {buildExitCode}).";
             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
             return new InstallerActionResult(false, msg);
         }

         var projectDirectory = Path.GetDirectoryName(l5xGitProjectFile) ?? repoDir;
         var outputExe = Directory
             .GetFiles(projectDirectory, "l5xgit.exe", SearchOption.AllDirectories)
             .Where(path => path.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}Release{Path.DirectorySeparatorChar}", StringComparison.OrdinalIgnoreCase))
             .OrderByDescending(File.GetLastWriteTimeUtc)
             .FirstOrDefault()
             ?? Directory
                 .GetFiles(repoDir, "l5xgit.exe", SearchOption.AllDirectories)
                 .OrderByDescending(File.GetLastWriteTimeUtc)
                 .FirstOrDefault();

         if (string.IsNullOrWhiteSpace(outputExe) || !File.Exists(outputExe))
         {
             const string msg = "Build completed, but l5xgit.exe was not found in build outputs.";
             AppLogger.Warn($"InstallAndBuildRockwellVcsToolsAsync failed: {msg}");
             return new InstallerActionResult(false, msg);
         }

         AppLogger.Info($"InstallAndBuildRockwellVcsToolsAsync completed successfully. l5xgit.exe: {outputExe}");
         onOutput($"[vcs] Built l5xgit.exe: {outputExe}");
         return new InstallerActionResult(true, "Rockwell VCS tools were built successfully.", outputExe);
     }

     /// <summary>
     /// Copies the built CustomToolsMenu.xml into the Studio 5000 common folder, backing up any existing file.
     /// If elevation is required, requests UAC consent for the copy step.
     /// </summary>
     public async Task<InstallerActionResult> InstallStudioCustomToolsMenuAsync(Action<string> onOutput, CancellationToken cancellationToken = default)
     {
         AppLogger.Info("InstallStudioCustomToolsMenuAsync starting.");

         var repoDir = GetRockwellVcsRepoDirectory();
         var source = Path.Combine(repoDir, "artifacts", "bin", "Release", "Assets", "CustomToolsMenu.xml");
         var destination = StudioCustomToolsDestination;
         var destinationDirectory = Path.GetDirectoryName(destination) ?? string.Empty;

         if (!File.Exists(source))
         {
             var msg = $"Source file not found: {source}. Build Rockwell VCS tools first.";
             AppLogger.Warn($"InstallStudioCustomToolsMenuAsync failed: {msg}");
             return new InstallerActionResult(false, msg);
         }

         if (!Directory.Exists(destinationDirectory))
         {
             var msg = $"Studio 5000 common directory not found: {destinationDirectory}. Is Logix Designer installed?";
             AppLogger.Warn($"InstallStudioCustomToolsMenuAsync failed: {msg}");
             return new InstallerActionResult(false, msg);
         }

         onOutput("[studio] Installing CustomToolsMenu.xml into Studio 5000 common directory...");

         if (IsRunningAsAdministrator())
         {
             try
             {
                 var backupPath = BackupExistingDestination(destination);
                 if (backupPath is not null)
                     onOutput($"[studio] Backed up existing file to: {backupPath}");

                 File.Copy(source, destination, overwrite: true);
                 var msg = $"Installed CustomToolsMenu.xml to {destination}.";
                 AppLogger.Info($"InstallStudioCustomToolsMenuAsync completed: {msg}");
                 return new InstallerActionResult(true, msg);
             }
             catch (Exception ex)
             {
                 AppLogger.Error("InstallStudioCustomToolsMenuAsync copy failed.", ex);
                 return new InstallerActionResult(false, $"Failed to install custom tools menu: {ex.Message}");
             }
         }

         onOutput("[studio] Requesting administrator privileges for Studio 5000 custom tools install...");
         var elevationResult = await RunElevatedStudioCustomToolsInstallAsync(source, destination, cancellationToken);
         if (!elevationResult.Success)
         {
             AppLogger.Warn($"InstallStudioCustomToolsMenuAsync failed: {elevationResult.Message}");
             return elevationResult;
         }

         AppLogger.Info($"InstallStudioCustomToolsMenuAsync completed: {elevationResult.Message}");
         return elevationResult;
     }

     private static string? TryReadRockwellPackageSource(string repoDir)
     {
         try
         {
             var nugetConfigPath = Path.Combine(repoDir, "nuget.config");
             if (!File.Exists(nugetConfigPath))
                 return null;

             var doc = XDocument.Load(nugetConfigPath);
             var sourceElement = doc
                 .Descendants("add")
                 .FirstOrDefault(x =>
                     string.Equals((string?)x.Attribute("key"), "rockwell-local-packages", StringComparison.OrdinalIgnoreCase));

             var value = (string?)sourceElement?.Attribute("value");
             if (string.IsNullOrWhiteSpace(value))
                 return null;

             var normalized = value.Replace('/', Path.DirectorySeparatorChar);
             return Path.GetFullPath(normalized);
         }
         catch (Exception ex)
         {
             AppLogger.Warn($"Unable to parse nuget.config for Rockwell package source. {ex.Message}");
             return null;
         }
     }

     private static string GetToolsRoot()
     {
         return Path.Combine(
             Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
             "ABLogixGitManager",
             "tools");
     }

     private static string GetRockwellVcsRepoDirectory()
     {
         return Path.Combine(GetToolsRoot(), "ra-logix-designer-vcs-custom-tools");
     }

     private static bool IsRunningAsAdministrator()
     {
         var identity = WindowsIdentity.GetCurrent();
         var principal = new WindowsPrincipal(identity);
         return principal.IsInRole(WindowsBuiltInRole.Administrator);
     }

     private static string? BackupExistingDestination(string destinationPath)
     {
         if (!File.Exists(destinationPath))
             return null;

         var index = 1;
         var backupPath = $"{destinationPath}.bak{index}";
         while (File.Exists(backupPath))
         {
             index++;
             backupPath = $"{destinationPath}.bak{index}";
         }

         File.Move(destinationPath, backupPath);
         return backupPath;
     }

     private static async Task<InstallerActionResult> RunElevatedStudioCustomToolsInstallAsync(
         string sourcePath,
         string destinationPath,
         CancellationToken cancellationToken)
     {
         var scriptPath = Path.Combine(Path.GetTempPath(), $"ablogix-install-customtools-{Guid.NewGuid():N}.ps1");
         var scriptContent = """
 param(
     [Parameter(Mandatory = $true)][string]$SourcePath,
     [Parameter(Mandatory = $true)][string]$DestinationPath
 )
 $ErrorActionPreference = 'Stop'
 $destDir = Split-Path $DestinationPath -Parent
 if (-not (Test-Path $destDir)) { throw "Destination directory not found: $destDir" }
 if (-not (Test-Path $SourcePath)) { throw "Source file not found: $SourcePath" }
 if (Test-Path $DestinationPath) {
     $i = 1
     while (Test-Path "$DestinationPath.bak$i") { $i++ }
     Move-Item -Path $DestinationPath -Destination "$DestinationPath.bak$i"
 }
 Copy-Item -Path $SourcePath -Destination $DestinationPath -Force
 """;

         try
         {
             File.WriteAllText(scriptPath, scriptContent);

             var psi = new ProcessStartInfo("powershell")
             {
                 UseShellExecute = true,
                 Verb = "runas",
             };
             psi.ArgumentList.Add("-NoProfile");
             psi.ArgumentList.Add("-ExecutionPolicy");
             psi.ArgumentList.Add("Bypass");
             psi.ArgumentList.Add("-File");
             psi.ArgumentList.Add(scriptPath);
             psi.ArgumentList.Add("-SourcePath");
             psi.ArgumentList.Add(sourcePath);
             psi.ArgumentList.Add("-DestinationPath");
             psi.ArgumentList.Add(destinationPath);

             using var process = Process.Start(psi);
             if (process is null)
                 return new InstallerActionResult(false, "Failed to start elevated install process.");

             await process.WaitForExitAsync(cancellationToken);

             if (process.ExitCode != 0)
                 return new InstallerActionResult(false, $"Elevated install failed with exit code {process.ExitCode}.");

             return new InstallerActionResult(true, $"Installed CustomToolsMenu.xml to {destinationPath}.");
         }
         catch (OperationCanceledException)
         {
             return new InstallerActionResult(false, "Custom tools menu install was cancelled.");
         }
         catch (Exception ex)
         {
             return new InstallerActionResult(false, $"Failed to install Studio 5000 custom tools menu: {ex.Message}");
         }
         finally
         {
             try
             {
                 if (File.Exists(scriptPath))
                     File.Delete(scriptPath);
             }
             catch (Exception ex)
             {
                 AppLogger.Warn($"Unable to delete temporary script '{scriptPath}': {ex.Message}");
             }
         }
     }

     /// <summary>
     /// Runs a process, streams output to the caller, and returns exit code and combined output.
     /// </summary>
     private static async Task<(int ExitCode, string CombinedOutput)> RunProcessAsync(
         string exePath,
         IEnumerable<string> arguments,
         Action<string> onOutput,
         CancellationToken cancellationToken)
     {
         var psi = new ProcessStartInfo(exePath)
         {
             RedirectStandardOutput = true,
             RedirectStandardError = true,
             UseShellExecute = false,
             CreateNoWindow = true,
         };

         foreach (var argument in arguments)
             psi.ArgumentList.Add(argument);

         AppLogger.Info($"Dependency installer launching: {exePath} {string.Join(" ", psi.ArgumentList.Select(a => $"\"{a}\""))}");

         using var process = Process.Start(psi);
         if (process is null)
             throw new InvalidOperationException($"Failed to start process: {exePath}");

         var outputLines = new List<string>();

         process.OutputDataReceived += (_, eventArgs) =>
         {
             if (eventArgs.Data is null)
                 return;

             outputLines.Add(eventArgs.Data);
             onOutput(eventArgs.Data);
         };

         process.ErrorDataReceived += (_, eventArgs) =>
         {
             if (eventArgs.Data is null)
                 return;

             outputLines.Add(eventArgs.Data);
             onOutput($"[stderr] {eventArgs.Data}");
         };

         process.BeginOutputReadLine();
         process.BeginErrorReadLine();

         await process.WaitForExitAsync(cancellationToken);

         var combinedOutput = string.Join(Environment.NewLine, outputLines);
         return (process.ExitCode, combinedOutput);
     }
 }

