 using System.Collections.ObjectModel;
 using System.IO;
 using System.Windows;
 using CommunityToolkit.Mvvm.ComponentModel;
 using CommunityToolkit.Mvvm.Input;
 using ABLogixGitManager.Models;
 using ABLogixGitManager.Services;

 namespace ABLogixGitManager.ViewModels;

 /// <summary>
 /// View model for the Settings / Dependency Center window.
 /// Owns the dependency scan operation and exposes the results as an observable list.
 /// </summary>
 public partial class SettingsViewModel : ObservableObject
 {
     private readonly DependencyCheckerService _checker = new();
     private readonly DependencyInstallerService _installer = new();
     private readonly AppConfigService _configService = new();

     /// <summary>Current path to l5xgit.exe, editable by the user in the Settings window.</summary>
     [ObservableProperty]
     private string _l5xGitExePath;

     /// <summary><c>true</c> while a dependency scan is in progress.</summary>
     [ObservableProperty]
     [NotifyCanExecuteChangedFor(nameof(InstallDotNetSdkCommand))]
     [NotifyCanExecuteChangedFor(nameof(InstallAndBuildRockwellVcsToolsCommand))]
     [NotifyCanExecuteChangedFor(nameof(InstallStudioCustomToolsMenuCommand))]
     [NotifyPropertyChangedFor(nameof(CanUseExistingL5xGit))]
     private bool _isScanning;

     /// <summary>Short status message shown above the dependency list.</summary>
     [ObservableProperty]
     private string _scanStatus = "Click Rescan to check dependencies.";

     /// <summary><c>true</c> while an install/build action is in progress.</summary>
     [ObservableProperty]
     [NotifyCanExecuteChangedFor(nameof(InstallDotNetSdkCommand))]
     [NotifyCanExecuteChangedFor(nameof(InstallAndBuildRockwellVcsToolsCommand))]
     [NotifyCanExecuteChangedFor(nameof(InstallStudioCustomToolsMenuCommand))]
     [NotifyPropertyChangedFor(nameof(CanUseExistingL5xGit))]
     private bool _isActionBusy;

     /// <summary>
     /// <c>true</c> when the last scan found a Ready .NET SDK 10. When set, the SDK
     /// install action is disabled because the prerequisite is already satisfied.
     /// </summary>
     [ObservableProperty]
     [NotifyCanExecuteChangedFor(nameof(InstallDotNetSdkCommand))]
     private bool _isDotNetSdkReady;

     /// <summary>
     /// <c>true</c> when the last scan found a Ready Rockwell VCS Tools (l5xgit). When set,
     /// the download/compile and use-existing actions are disabled — nothing more to install.
     /// </summary>
     [ObservableProperty]
     [NotifyCanExecuteChangedFor(nameof(InstallAndBuildRockwellVcsToolsCommand))]
     [NotifyPropertyChangedFor(nameof(CanUseExistingL5xGit))]
     private bool _isL5xGitReady;

     /// <summary>
     /// <c>true</c> when Studio 5000 is detected. Controls visibility/enabled state of the
     /// "Add Custom Tools to Studio 5000" action.
     /// </summary>
     [ObservableProperty]
     [NotifyCanExecuteChangedFor(nameof(InstallStudioCustomToolsMenuCommand))]
     private bool _isStudio5000Detected;

     /// <summary>
     /// <c>true</c> when the "Use existing l5xgit.exe" action may run: no scan or install
     /// is in progress and l5xgit is not already Ready.
     /// </summary>
     public bool CanUseExistingL5xGit => !IsActionBusy && !IsScanning && !IsL5xGitReady;

     /// <summary>Short status line for install/build actions.</summary>
     [ObservableProperty]
     private string _actionStatus = "No setup action running.";

     /// <summary>Streaming output from install/build actions shown in the settings window.</summary>
     [ObservableProperty]
     private string _actionLogOutput = string.Empty;

     /// <summary>One row per dependency, displayed in order of importance.</summary>
     public ObservableCollection<DependencyItemViewModel> Dependencies { get; } = [];

     /// <summary>
     /// Initialises the view model with seed rows (all <see cref="DependencyStatus.Unknown"/>)
     /// so the list renders immediately before the first scan runs.
     /// </summary>
     /// <param name="currentL5xGitExePath">The l5xgit.exe path from the current configuration.</param>
     public SettingsViewModel(string currentL5xGitExePath)
     {
         _l5xGitExePath = currentL5xGitExePath;

         // Seed rows so the list renders immediately with Unknown status.
         Dependencies.Add(new DependencyItemViewModel(
             new DependencyInfo("Studio 5000 & Logix SDK", DependencyStatus.Unknown),
             "ACD conversion for commit and restore"));
         Dependencies.Add(new DependencyItemViewModel(
             new DependencyInfo(".NET SDK 10", DependencyStatus.Unknown),
             "building Rockwell VCS tools from source"));
         Dependencies.Add(new DependencyItemViewModel(
             new DependencyInfo("Rockwell VCS Tools (l5xgit)", DependencyStatus.Unknown),
             "commit and pull/restore operations"));
         Dependencies.Add(new DependencyItemViewModel(
             new DependencyInfo("Git for Windows", DependencyStatus.Unknown),
             "pull/restore operations"));

         AppLogger.Info($"SettingsViewModel initialised with l5xgit path: '{currentL5xGitExePath}'.");
     }

     // -------------------------------------------------------------------------
     // Commands
     // -------------------------------------------------------------------------

     /// <summary>
     /// Runs all dependency probes concurrently, then updates each row in the list.
     /// Sets all rows to <see cref="DependencyStatus.Scanning"/> immediately so the UI
     /// reflects progress before results arrive.
     /// </summary>
     [RelayCommand]
     private async Task RescanAsync()
     {
         if (IsScanning) return;

         IsScanning = true;
         ScanStatus = "Scanning…";
         AppLogger.Info("Dependency rescan requested by user.");

         // Mark all as scanning so the UI reflects progress immediately.
         foreach (var item in Dependencies)
             item.Status = DependencyStatus.Scanning;

         try
         {
             var allResultsTask = _checker.CheckAllAsync(l5xGitPath: L5xGitExePath);
             var studioResultTask = _checker.CheckStudio5000Async();
             await Task.WhenAll(allResultsTask, studioResultTask);
             var results = allResultsTask.Result;

             Application.Current.Dispatcher.Invoke(() =>
             {
                 for (int i = 0; i < results.Count && i < Dependencies.Count; i++)
                     Dependencies[i].ApplyResult(results[i]);

                 // Disable install actions for prerequisites that are already satisfied.
                 IsDotNetSdkReady = results.Any(
                     r => r.Name == ".NET SDK 10" && r.Status == DependencyStatus.Ready);
                 IsL5xGitReady = results.Any(
                     r => r.Name == "Rockwell VCS Tools (l5xgit)" && r.Status == DependencyStatus.Ready);
                 IsStudio5000Detected = studioResultTask.Result.Status == DependencyStatus.Ready;

                 var readyCount = results.Count(r => r.Status == DependencyStatus.Ready);
                 ScanStatus = $"Scan complete — {readyCount} of {results.Count} dependencies ready.";
             });
         }
         catch (Exception ex)
         {
             ScanStatus = $"Scan failed: {ex.Message}";
             AppLogger.Error("Dependency scan failed.", ex);
         }
         finally
         {
             IsScanning = false;
         }
     }

     /// <summary>
     /// Installs the .NET 10 SDK for source-build workflows and rescans dependencies.
     /// </summary>
     [RelayCommand(CanExecute = nameof(CanInstallDotNetSdk))]
     private async Task InstallDotNetSdkAsync()
     {
         IsActionBusy = true;
         ActionStatus = "Installing .NET SDK 10...";
         AppendActionLog("[setup] Starting .NET SDK 10 install.");
         AppLogger.Info("InstallDotNetSdkAsync command started.");

         try
         {
             var result = await _installer.InstallDotNetSdk10Async(AppendActionLog);
             ActionStatus = result.Message;
             AppendActionLog(result.Success ? $"[done] {result.Message}" : $"[error] {result.Message}");
             AppLogger.Info($"InstallDotNetSdkAsync command completed. Success={result.Success}. Message={result.Message}");
         }
         catch (Exception ex)
         {
             ActionStatus = $"SDK install failed: {ex.Message}";
             AppendActionLog($"[error] SDK install failed: {ex.Message}");
             AppLogger.Error("InstallDotNetSdkAsync command failed.", ex);
         }
         finally
         {
             IsActionBusy = false;
         }

         await RescanAsync();
     }

     /// <summary>
     /// Clones/updates Rockwell VCS tools, builds l5xgit.exe, saves the detected path, and rescans dependencies.
     /// </summary>
     [RelayCommand(CanExecute = nameof(CanInstallRockwellVcsTools))]
     private async Task InstallAndBuildRockwellVcsToolsAsync()
     {
         IsActionBusy = true;
         ActionStatus = "Installing and building Rockwell VCS tools...";
         AppendActionLog("[setup] Starting Rockwell VCS tools install/build.");
         AppLogger.Info("InstallAndBuildRockwellVcsToolsAsync command started.");

         try
         {
             var result = await _installer.InstallAndBuildRockwellVcsToolsAsync(AppendActionLog);
             ActionStatus = result.Message;

             if (result.Success && !string.IsNullOrWhiteSpace(result.L5xGitExePath))
             {
                 SaveConfiguredL5xGitPath(result.L5xGitExePath);
                 ActionStatus = "Download + compile complete. l5xgit.exe was automatically associated.";
                 AppendActionLog($"[settings] Saved l5xgit.exe path: {result.L5xGitExePath}");
             }
             else
             {
                 AppendActionLog(result.Success ? $"[done] {result.Message}" : $"[error] {result.Message}");
             }

             AppLogger.Info($"InstallAndBuildRockwellVcsToolsAsync command completed. Success={result.Success}. Message={result.Message}");
         }
         catch (Exception ex)
         {
             ActionStatus = $"VCS tools setup failed: {ex.Message}";
             AppendActionLog($"[error] VCS tools setup failed: {ex.Message}");
             AppLogger.Error("InstallAndBuildRockwellVcsToolsAsync command failed.", ex);
         }
         finally
         {
             IsActionBusy = false;
         }

         await RescanAsync();
     }

     /// <summary>
     /// Installs Rockwell's CustomToolsMenu.xml into Studio 5000 common tools location.
     /// This action is only available when Studio 5000 is detected.
     /// </summary>
     [RelayCommand(CanExecute = nameof(CanInstallStudioCustomToolsMenu))]
     private async Task InstallStudioCustomToolsMenuAsync()
     {
         IsActionBusy = true;
         ActionStatus = "Installing Custom Tools menu into Studio 5000...";
         AppendActionLog("[setup] Starting Studio 5000 custom tools menu install.");
         AppLogger.Info("InstallStudioCustomToolsMenuAsync command started.");

         try
         {
             var result = await _installer.InstallStudioCustomToolsMenuAsync(AppendActionLog);
             ActionStatus = result.Message;
             AppendActionLog(result.Success ? $"[done] {result.Message}" : $"[error] {result.Message}");
             AppLogger.Info($"InstallStudioCustomToolsMenuAsync command completed. Success={result.Success}. Message={result.Message}");
         }
         catch (Exception ex)
         {
             ActionStatus = $"Studio custom tools menu install failed: {ex.Message}";
             AppendActionLog($"[error] Studio custom tools menu install failed: {ex.Message}");
             AppLogger.Error("InstallStudioCustomToolsMenuAsync command failed.", ex);
         }
         finally
         {
             IsActionBusy = false;
         }
     }

     /// <summary>
     /// Uses an already-compiled l5xgit.exe selected by the user, then rescans dependencies.
     /// </summary>
     public async Task SetExistingL5xGitPathAsync(string selectedExePath)
     {
         AppLogger.Info($"SetExistingL5xGitPathAsync called with path: {selectedExePath}");

         if (string.IsNullOrWhiteSpace(selectedExePath))
         {
             ActionStatus = "No file was selected.";
             AppendActionLog("[warning] No l5xgit.exe file was selected.");
             AppLogger.Warn("SetExistingL5xGitPathAsync aborted — empty path.");
             return;
         }

         if (!File.Exists(selectedExePath))
         {
             ActionStatus = $"Selected file does not exist: {selectedExePath}";
             AppendActionLog($"[error] File not found: {selectedExePath}");
             AppLogger.Warn($"SetExistingL5xGitPathAsync aborted — file not found: {selectedExePath}");
             return;
         }

         SaveConfiguredL5xGitPath(selectedExePath);
         ActionStatus = "Configured existing l5xgit.exe path.";
         AppendActionLog($"[done] Configured existing l5xgit.exe path: {selectedExePath}");

         await RescanAsync();
     }

     private bool CanInstallDotNetSdk() => !IsScanning && !IsActionBusy && !IsDotNetSdkReady;

     private bool CanInstallRockwellVcsTools() => !IsScanning && !IsActionBusy && !IsL5xGitReady;

     private bool CanInstallStudioCustomToolsMenu() => !IsScanning && !IsActionBusy && IsStudio5000Detected;

     private void SaveConfiguredL5xGitPath(string l5xGitExePath)
     {
         var config = _configService.Load();
         config.L5xGitExePath = l5xGitExePath;
         _configService.Save(config);

         L5xGitExePath = l5xGitExePath;
         AppLogger.Info($"Saved l5xgit.exe path from Settings: {l5xGitExePath}");
     }

     private void AppendActionLog(string message)
     {
         var ts = DateTime.Now.ToString("HH:mm:ss");
         ActionLogOutput += $"[{ts}] {message}{Environment.NewLine}";
     }
 }
